    jsonb_build_object(
      'content_contract_version',6,
      'search_intent_questions',jsonb_build_array('ما معنى Joining في العلاج الأسري؟','ما الفرق بين Joining والتحالف العلاجي؟','ما هو Tracking في العلاج البنيوي؟','ما هو Selective Joining؟','كيف يعمل Joining مع المراهقين؟','كيف تتأثر مهارة Joining بالثقافة؟','متى يفشل الانضمام وكيف يصلح؟','متى لا تكون الجلسة المشتركة آمنة؟'),
      'claim_source_map',jsonb_build_array(
        jsonb_build_object('claim','Joining مكون أساسي في BSFT ويعمل على مستوى الفرد والأسرة','sources',jsonb_build_array('bsft-systematic-2013','bsft-engagement-2014')),
