        jsonb_build_object('claim','دراسة محادثية للعلاج البنيوي أوضحت كيف يحقق المعالج تغيير الأدوار داخل الجلسة عبر موارد تفاعلية قابلة للملاحظة','sources',jsonb_build_array('change-family-therapy-2020')),
        jsonb_build_object('claim','مراجعة منهجية حول إشراك الأطفال جمعت 64 منشورًا ووصفت تقنيات بنيوية وعملية لإدخالهم في العلاج الأسري','sources',jsonb_build_array('children-family-therapy-review-2002')),
